import{_ as s,o as l,c as e,a0 as n}from"./chunks/framework.DqMqoJl9.js";const r="/assets/3-code_20210624103921.9kCKnCwc.png",_=JSON.parse('{"title":"代码优化","description":"","frontmatter":{},"headers":[],"relativePath":"performance/3-code.md","filePath":"performance/3-code.md","lastUpdated":1791573371000}'),o={name:"performance/3-code.md"};function i(t,a,p,c,d,h){return l(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="代码优化" tabindex="-1">代码优化 <a class="header-anchor" href="#代码优化" aria-label="Permalink to &quot;代码优化&quot;">​</a></h1><h2 id="_1-js-缩短解析时间" tabindex="-1">1 JS 缩短解析时间 <a class="header-anchor" href="#_1-js-缩短解析时间" aria-label="Permalink to &quot;1 JS 缩短解析时间&quot;">​</a></h2><p>加载一个 js 资源要比加载一个图片资源耗时长的多，js 加载后还需要耗时解析和执行</p><p><img src="'+r+`" alt=""></p><p>我们要做的优化就是缩小 js 的大小，加快解析和执行的时间</p><p><strong>解决方案：</strong></p><ul><li>压缩 js</li><li>代码拆分，按需加载</li><li>Tree shaking 清除没用到的代码</li></ul><h2 id="_2-配合-v8-有效优化代码" tabindex="-1">2 配合 V8 有效优化代码 <a class="header-anchor" href="#_2-配合-v8-有效优化代码" aria-label="Permalink to &quot;2 配合 V8 有效优化代码&quot;">​</a></h2><h2 id="_3-函数优化" tabindex="-1">3 函数优化 <a class="header-anchor" href="#_3-函数优化" aria-label="Permalink to &quot;3 函数优化&quot;">​</a></h2><p><strong>函数有两种解析方式：</strong></p><ol><li>懒解析 (lazy parsing)：默认的解析方式。函数声明的时候不解析，而是在使用的时候解析。这就不需要提前为函数创建语法树，能加快解析速度节约资源</li><li>饥饿解析 (eager parsing)：快速解析</li></ol><p>一般的函数默认懒解析就可以，需要立即执行的函数在声明时建议进行饥饿解析</p><p>将函数用小括号包裹会进行饥饿解析：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">(</span><span style="color:#D73A49;">function</span><span style="color:#6F42C1;"> add</span><span style="color:#24292E;">(</span><span style="color:#E36209;">a</span><span style="color:#24292E;">, </span><span style="color:#E36209;">b</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#D73A49;">  return</span><span style="color:#24292E;"> a </span><span style="color:#D73A49;">+</span><span style="color:#24292E;"> b;</span></span>
<span class="line"><span style="color:#24292E;">});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="_4-对象优化" tabindex="-1">4 对象优化 <a class="header-anchor" href="#_4-对象优化" aria-label="Permalink to &quot;4 对象优化&quot;">​</a></h2><p><strong>对象可以做的优化：</strong></p><ol><li>以相同的顺序初始化对象成员，避免隐藏类的调整</li><li>实例化后避免添加新属性</li><li>尽量使用 Array 代替 Array like 对象</li></ol><p>浏览器引擎对 js 运行做了很多优化，这里的优化只要是迎合引擎的优化，即迎合引擎的优化规则</p><h2 id="_5-html-优化" tabindex="-1">5 HTML 优化 <a class="header-anchor" href="#_5-html-优化" aria-label="Permalink to &quot;5 HTML 优化&quot;">​</a></h2><ul><li>减少 iframes 的使用，会阻碍父文档的加载。要用的话尽量延时加载，让父文档先加载完</li><li>压缩代码</li><li>避免节点深层级嵌套 (渲染更慢)</li><li>避免 table 布局 (渲染更慢)</li></ul><h2 id="_6-css-优化" tabindex="-1">6 CSS 优化 <a class="header-anchor" href="#_6-css-优化" aria-label="Permalink to &quot;6 CSS 优化&quot;">​</a></h2><ul><li>降低 CSS 对渲染的阻塞</li><li>利用 GPU 完成动画</li><li>使用 contain 属性 (表示当前元素不影响外部的元素，浏览器渲染时只对这个元素做更新)</li><li>使用 font-display 属性</li></ul>`,22)])])}const m=s(o,[["render",i]]);export{_ as __pageData,m as default};
